window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["reinforcement-learning"]={"title":"强化学习：从延迟反馈中学习决策策略","subtitle":"用 MDP、回报、价值函数、Bellman 方程、探索与策略梯度理解 Agent 如何在交互中优化长期结果。","thesis":"强化学习优化的不是单步答案，而是策略在环境中产生的<b>长期期望回报</b>；难点来自奖励延迟、探索成本、分布随策略改变和奖励代理错位。","quality":{"contractVersion":2,"examples":[{"section":7,"evidence":{"setup":"35 天质量问题退款","rule":"γ=0.9 的 G","steps":"直接承诺","interpretation":"若奖励只记录即时满意"}}],"sectionContracts":[{"section":1,"definition":{"answer":"强化学习是智能体通过连续交互学习决策策略的框架。","evidence":"强化学习是让智能体通过连续交互学习决策策略的框架"},"problem":{"answer":"它用于处理动作改变未来且没有逐步标准答案的决策问题。","evidence":"用于处理动作会改变未来情境、没有逐步标准答案的问题"},"inputOutput":{"answer":"输入是状态，策略输出动作，环境输出奖励与下一状态。","evidence":"每一步输入当前状态，策略输出动作或动作概率，环境再返回奖励和下一状态"},"mechanism":{"answer":"训练流程先收集转移，再估计长期结果，最后更新策略并重复交互。","evidence":"训练流程先收集这类转移，再估计长期结果，最后更新策略"},"interpretation":{"answer":"高回报表示策略在当前环境和奖励定义下表现较好。","evidence":"高回报表示策略在当前环境与奖励定义下表现较好"},"boundary":{"answer":"状态遗漏、奖励错位和环境变化都可能使结论失效。","evidence":"都可能让结论失效"}},{"section":2,"definition":{"answer":"折扣回报是把当前以后多步奖励合成一个目标的量。","evidence":"折扣回报是把当前以后的一串奖励合成单一决策目标的量"},"problem":{"answer":"它解决即时奖励与长期后果发生冲突时怎样比较动作的问题。","evidence":"解决即时得分与长期后果冲突的问题"},"inputOutput":{"answer":"输入是奖励序列和折扣因子，输出是加权总回报。","evidence":"输入是未来奖励序列和折扣因子，输出从当前时刻开始的加权总和"},"mechanism":{"answer":"先按时间距离乘折扣幂，再把各步奖励相加。","evidence":"先按距离乘上 γ 的幂，再把各步奖励相加"},"interpretation":{"answer":"回报较大表示按当前时间偏好更值得选择。","evidence":"回报较大表示按当前时间偏好更值得"},"boundary":{"answer":"不同折扣、时间单位与终止规则的数值不能直接比较。","evidence":"不能直接比较，也不能证明奖励本身代表真实价值"}},{"section":3,"definition":{"answer":"价值函数描述特定策略下未来回报的期望估计。","evidence":"价值函数是特定策略下未来回报的期望估计"},"problem":{"answer":"它用于解决轨迹未结束时怎样评价当前状态或动作的问题。","evidence":"用于解决轨迹尚未结束时怎样评价当前状态或动作的问题"},"inputOutput":{"answer":"输入是状态或状态动作对，输出是 V 或 Q 价值。","evidence":"输入状态或状态—动作对，输出 V 或 Q"},"mechanism":{"answer":"先观察一步转移，再用奖励加折扣后继价值更新当前估计。","evidence":"先观察一步转移，再用 r+γV(s′) 修正当前估计"},"interpretation":{"answer":"高价值表示当前策略环境下的长期回报预期较高。","evidence":"价值较高表示在当前策略与环境下长期回报预期较高"},"boundary":{"answer":"价值不是事实，稀疏样本、分布外动作与近似都会造成偏差。","evidence":"不是事实标签；抽样稀少、分布外动作和函数近似"}},{"section":4,"definition":{"answer":"探索—利用权衡是一种在收益获取与信息收集之间做选择的决策。","evidence":"探索—利用权衡是一种在当前收益与信息收集之间做选择的决策"},"problem":{"answer":"它解决当前估计最优可能因样本不足而长期锁死的问题。","evidence":"可能改变未来选择的证据不足动作"},"inputOutput":{"answer":"输入是价值、不确定性和风险约束，输出是本步动作。","evidence":"输入动作价值、不确定性和风险约束，输出本步动作"},"mechanism":{"answer":"选择时先评估收益与证据，再用随机机会、策略熵或不确定性奖励决定动作。","evidence":"选择时先评估已有收益与证据，再由 ε-greedy"},"interpretation":{"answer":"估计排序改变表示新证据修正了旧判断。","evidence":"估计排序改变，说明新证据纠正了旧判断"},"boundary":{"answer":"高风险不可逆场景不能直接在线探索，必须使用受限环境。","evidence":"不能直接在线试错"}},{"section":5,"definition":{"answer":"价值法、策略梯度和 Actor–Critic 是改进策略的三类计算路线。","evidence":"描述的是三种利用经验改进策略的计算路线"},"problem":{"answer":"它们用于把经验中的长期回报转化为策略改进。","evidence":"利用经验改进策略"},"inputOutput":{"answer":"输入是状态、动作、回报或价值，输出价值、概率及参数。","evidence":"输入状态、动作、回报或价值估计，输出动作价值、策略概率和更新后的参数"},"mechanism":{"answer":"价值法先估 Q，策略梯度按优势更新，Actor–Critic 提供价值基线。","evidence":"价值法先估 Q 再选动作，策略梯度按优势调整概率"},"interpretation":{"answer":"回报与独立指标共同改善表示当前策略更新较为有效。","evidence":"表示当前更新在多项证据下有效"},"boundary":{"answer":"动作空间、估计偏差和奖励质量会限制算法，PPO 不保证安全。","evidence":"PPO 的小步约束也不等于安全保证"}},{"section":6,"definition":{"answer":"奖励与环境共同描述训练目标和智能体可见后果的边界。","evidence":"奖励与环境共同定义了训练所能“看见”的世界"},"problem":{"answer":"本节用于识别代理奖励与现实目标错位的问题。","evidence":"强化学习目标的边界"},"inputOutput":{"answer":"输入是奖励、状态、转移与权限，输出是可优化经验分布。","evidence":"输入是奖励规则、状态表示、转移和权限，输出是策略能够优化的经验分布"},"mechanism":{"answer":"策略先按规则行动，再寻找能够提高回报的行为模式。","evidence":"策略先在这些规则下行动，再寻找能提高回报的行为模式"},"interpretation":{"answer":"回报升而真实指标降表示目标已经错位。","evidence":"若真实解决率、安全切片或副作用恶化，就应解释为目标错位"},"boundary":{"answer":"遗漏后果、模拟差距和不可逆动作不能靠训练自动补回。","evidence":"都不能靠继续训练自动补回"}},{"section":7,"definition":{"answer":"退款案例是把延迟奖励归因到首个动作的信用分配演算。","evidence":"退款案例是一条完整的信用分配演算"},"problem":{"answer":"它解决即时满意与后续越权损失应怎样共同决定动作的问题。","evidence":"延迟后果足以推翻即时满意"},"inputOutput":{"answer":"输入是状态、动作、两步奖励和折扣，输出是回报与选择。","evidence":"输入订单状态、两个候选动作、两步奖励和折扣因子，输出各动作回报与首步选择"},"mechanism":{"answer":"先列即时奖励，再折扣后续奖励，最后比较两个回报。","evidence":"先列出即时奖励，再把后续奖励折扣回首个动作，最后比较"},"interpretation":{"answer":"先核验胜出表示长期后果推翻了短期收益。","evidence":"先核验胜出表示延迟后果足以推翻即时满意"},"boundary":{"answer":"状态缺失或奖励漏记可能让 TD 更快学到错误策略。","evidence":"都可能让 TD 更新更高效地学习错误策略"}},{"section":8,"definition":{"answer":"安全强化学习工作流是结合离线学习、受控验证和上线闸门的过程。","evidence":"安全强化学习工作流是把探索、离线估计、策略更新和上线闸门放进同一风险控制过程"},"problem":{"answer":"它用于降低危险探索、离线外推和策略突变风险。","evidence":"用于降低危险探索、离线外推和策略突变的风险"},"inputOutput":{"answer":"输入是日志、模拟器、安全集、策略与指标，输出策略和放行决定。","evidence":"输入历史日志、模拟器、安全动作集、候选策略和监控指标，输出受约束策略及放行或回滚决定"},"mechanism":{"answer":"先离线或沙箱学习，再保守估计与小流量验证，随后持续监控。","evidence":"先在离线或沙箱学习，再用保守估计和小流量验证，随后"},"interpretation":{"answer":"小步更新与离线高分只表示当前局部证据较好。","evidence":"只表示局部证据较好"},"boundary":{"answer":"分布外动作、非平稳环境和奖励投机不能只靠算法分数处理。","evidence":"不能只靠算法分数处理"}}],"formulas":[{"id":"rl-discounted-return","section":2,"formulaIndex":1,"symbols":[{"name":"G","meaning":"从当前时刻开始的折扣回报","evidence":"从 t 开始的折扣回报"},{"name":"t","meaning":"当前决策时刻","evidence":"t 是当前时刻"},{"name":"k","meaning":"奖励距离当前的步数","evidence":"k 表示奖励距离现在多少步"},{"name":"γ","meaning":"未来奖励的折扣因子","evidence":"γ （gamma）是 0 到 1 之间的 折扣因子"},{"name":"r","meaning":"对应未来时刻收到的奖励","evidence":"是对应未来奖励"}]},{"id":"rl-bellman-value","section":3,"formulaIndex":1,"symbols":[{"name":"V","meaning":"状态在策略下的期望回报","evidence":"Vπ(s) 回答"},{"name":"π","meaning":"从状态选择动作的策略","evidence":"遵循策略 π"},{"name":"s","meaning":"当前状态","evidence":"从状态 s 出发"},{"name":"s′","meaning":"执行动作后的下一状态","evidence":"s′ 是执行动作后的下一状态"},{"name":"E","meaning":"对策略与环境随机性取期望","evidence":"同时平均策略选择与环境随机性"},{"name":"r","meaning":"当前转移得到的一步奖励","evidence":"一步奖励"},{"name":"γ","meaning":"下一状态价值的折扣因子","evidence":"γ 是上一节定义的折扣因子"}]},{"id":"rl-policy-gradient","section":5,"formulaIndex":1,"symbols":[{"name":"J","meaning":"策略要最大化的期望回报目标","evidence":"J 是期望回报目标"},{"name":"θ","meaning":"参数化策略的可学习参数","evidence":"调整参数 θ"},{"name":"π","meaning":"给状态分配动作概率的策略","evidence":"策略 πθ(a|s) 输出动作概率"},{"name":"s","meaning":"策略观察到的状态","evidence":"状态—动作"},{"name":"a","meaning":"策略在状态中选择的动作","evidence":"已选动作概率"},{"name":"A","meaning":"动作相对状态基线的优势","evidence":"优势 A(s,a) 表示"},{"name":"E","meaning":"对交互经验取平均","evidence":"核心更新信号"}]}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>写出 MDP 与回报；区分价值与策略；解释探索和信用分配；连接 PPO 与 RLHF。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>交互而非固定答案<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">监督学习没有标准动作时，机器怎样从行动后果中学习？</p><p><b>强化学习</b>研究连续决策：一个行动会改变接下来看到的情境，评价它时必须把延迟后果也算进去。执行决策的一方叫 <b>Agent（智能体）</b>，它所处并能影响的外部系统叫<b>环境</b>。</p><p>每一步，环境先给出<b>状态 s</b>（当前与决策有关的信息）；Agent 按<b>策略 π</b>选择<b>动作 a</b>；环境再返回<b>奖励 r</b>和<b>下一状态 s′</b>。这组对象及其转移规则组成马尔可夫决策过程（MDP）。输入是当前状态，策略输出动作；学习的最终产物不是某一道题的固定答案，而是一套在不同状态下选择动作的策略。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>对象</th><th>退款助手例子</th><th>作用</th></tr></thead><tbody><tr><td>状态 s</td><td>订单日期、权限、证据是否齐全</td><td>提供当前决策所需信息</td></tr><tr><td>动作 a</td><td>直接退款、要求核验、转人工</td><td>改变环境与后续状态</td></tr><tr><td>奖励 r</td><td>正确解决、用户摩擦、越权损失</td><td>提供可计算的目标代理</td></tr><tr><td>策略 π(a|s)</td><td>每种处理动作的选择概率</td><td>把状态映射为动作</td></tr></tbody></table></div><p>这与固定训练集监督学习不同：数据由当前策略主动产生，动作还会改变未来可见状态，所以训练分布会随策略更新而变化。若状态漏掉权限或证据等关键信息，再好的算法也无法区分本应采取不同动作的情境。</p><p>强化学习是让智能体通过连续交互学习决策策略的框架，用于处理动作会改变未来情境、没有逐步标准答案的问题。每一步输入当前状态，策略输出动作或动作概率，环境再返回奖励和下一状态；训练流程先收集这类转移，再估计长期结果，最后更新策略并重复交互。高回报表示策略在当前环境与奖励定义下表现较好，但状态遗漏、奖励错位或环境变化都可能让结论失效。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>折扣回报<span class=\"dd-badge math\">数学</span></h2><p class=\"dd-lead\">单步奖励可能与最终结果冲突，怎样把未来多步奖励合成一个目标？</p><p>强化学习通常最大化<b>回报</b>：从当前时刻开始，把以后收到的奖励按远近加权后相加。它把“先付出一点成本、以后获得更大收益”与“眼前得分高、以后代价巨大”放到同一把尺上。</p><div class=\"dd-formula\">Gₜ=Σ<sub>k≥0</sub> γᵏ rₜ₊ₖ₊₁</div><p>逐项读：<code>t</code> 是当前时刻；<code>k</code> 表示奖励距离现在多少步；<code>rₜ₊ₖ₊₁</code> 是对应未来奖励；<code>γ</code>（gamma）是 0 到 1 之间的<b>折扣因子</b>，<code>γᵏ</code> 让较远奖励权重逐步减小；<code>Gₜ</code> 是从 t 开始的折扣回报。</p><p>例如现在得到 −1、下一步得到 +8，取 <code>γ=0.9</code>，两步回报为 <code>G=−1+0.9×8=6.2</code>。若只看即时奖励会拒绝 −1，回报却说明这一步值得。γ 小会偏短期，γ 大更重视远期，同时让更长的因果链增加信用分配难度；有限任务也可以在终止状态直接停止求和。γ 表达时间偏好与任务时间尺度，不是越大越正确。</p><p>折扣回报是把当前以后的一串奖励合成单一决策目标的量，解决即时得分与长期后果冲突的问题。输入是未来奖励序列和折扣因子，输出从当前时刻开始的加权总和；计算时先按距离乘上 <code>γ</code> 的幂，再把各步奖励相加。回报较大表示按当前时间偏好更值得，但不同 γ、时间单位和终止规则下的数字不能直接比较，也不能证明奖励本身代表真实价值。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>价值与 Bellman 递推<span class=\"dd-badge math\">原理</span></h2><p class=\"dd-lead\">还没走完整条轨迹时，当前状态的好坏怎样连接到下一步？</p><p><b>价值函数</b>把未来许多种可能轨迹压成一个期望回报。<code>Vπ(s)</code> 回答“从状态 s 出发并一直遵循策略 π，平均能得到多少回报”；<code>Qπ(s,a)</code> 还固定第一步动作 a，回答“现在先做 a、之后遵循 π，平均能得到多少回报”。输入分别是状态或状态—动作对，输出都是回报估计。</p><p><b>Bellman 递推</b>不是另一种奖励，而是把一个长问题拆成“一步奖励 + 下一状态剩余价值”：</p><div class=\"dd-formula\">V<sup>π</sup>(s)=E<sub>π</sub>[r+γV<sup>π</sup>(s′)]</div><p>式中 <code>s′</code> 是执行动作后的下一状态，<code>γ</code> 是上一节定义的折扣因子，用来降低下一状态中较远奖励的权重；<code>Eπ</code> 表示同时平均策略选择与环境随机性。这个拆分让我们无需等到所有轨迹结束，就能用后继状态的估计更新当前价值；时序差分（TD）正是利用这种“用估计更新估计”的办法。</p><p>价值是特定策略、环境和数据下的期望估计，不是事实标签。同一状态的一次幸运轨迹不等于高价值。最优 Bellman 方程会对动作取最大值，但近似 Q 对未见动作估得过高时，max 会优先选中错误高估，需要双重估计、目标网络或保守离线方法缓解。</p><p>价值函数是特定策略下未来回报的期望估计，Bellman 递推则把长远价值拆成眼前奖励与下一状态价值。它们用于解决轨迹尚未结束时怎样评价当前状态或动作的问题：输入状态或状态—动作对，输出 V 或 Q；更新先观察一步转移，再用 <code>r+γV(s′)</code> 修正当前估计。价值较高表示在当前策略与环境下长期回报预期较高，不是事实标签；抽样稀少、分布外动作和函数近似都可能产生偏差。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>探索与利用<span class=\"dd-badge eng\">决策</span></h2><p class=\"dd-lead\">总选当前最优动作为何可能永远学不到更好策略？</p><p><b>根本原因是：当前最优只是“根据已有样本估计最好”，不等于真实最好。</b>动作价值来自尝试后的奖励；一个动作若很少被试，它的估计可能因偶然坏结果而偏低，也可能根本没有足够数据。Agent 若从此只选当前第一名，第一名会不断获得新数据，其他动作却永远没有翻身证据，于是早期误差会被自己的选择永久固定。</p><div class=\"dd-note key\"><b>最小例子：</b>按钮 A 的真实平均奖励是 6，按钮 B 是 8。第一次各试一次时，A 偶然得到 7，B 偶然得到 2。纯贪心策略此后总选估计值 7 的 A；因为再也不试 B，它永远看不到 B 长期平均其实更高。探索的作用不是“故意做差”，而是花一部分机会购买信息，纠正这种由样本不足造成的误判。</div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>方法</th><th>每次怎样选动作</th><th>为什么能打破锁死</th><th>边界</th></tr></thead><tbody><tr><td>ε-greedy</td><td>以 1−ε 选择当前最优，以 ε 随机选择其他动作</td><td>给低估或尚未充分尝试的动作持续留下被观察的机会</td><td>随机探索不看信息价值，动作很多或代价很高时会浪费尝试</td></tr><tr><td>熵奖励</td><td>在任务奖励外，奖励较分散的动作概率，避免策略过早变成“只选一个”</td><td>让多个候选动作在训练早期仍有采样概率，从而还能比较其长期后果</td><td>熵系数过大会长期保持随机；它鼓励多样，不保证试到最有信息的动作</td></tr><tr><td>置信上界 UCB</td><td>比较“估计收益＋不确定性奖励”，少试的动作因不确定性大而暂时加分</td><td>把尝试优先给“可能很好但证据不足”的动作；数据增多后奖励自动缩小</td><td>需要可信的不确定性估计，复杂状态和非平稳环境中实现更难</td></tr></tbody></table></div><p>因此“利用”是在当前证据下拿收益，“探索”是在可能改变未来决策时收集证据。现实系统常在模拟器、影子模式或安全约束内探索；重复已知坏动作只增加风险，并不减少关键不确定性。高风险未知动作应交给离线实验、人工审批或可回滚环境，不能用“需要探索”替无边界试错辩护。</p><p>探索—利用权衡是一种在当前收益与信息收集之间做选择的决策：利用选择当前估计最好的动作，探索则尝试可能改变未来选择的证据不足动作。它输入动作价值、不确定性和风险约束，输出本步动作；选择时先评估已有收益与证据，再由 ε-greedy 留出随机机会、熵奖励保持概率分散，或让 UCB 把收益与不确定性相加后比较。探索后估计排序改变，说明新证据纠正了旧判断；高风险或不可逆环境中不能直接在线试错，探索必须转移到模拟、离线或审批范围内。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>价值法与策略梯度<span class=\"dd-badge math\">算法</span></h2><p class=\"dd-lead\">知道回报与价值后，究竟有哪些办法把策略变得更好？</p><p><b>价值法</b>先学习动作价值 Q，再选择估计价值较高的动作。DQN 就是用神经网络近似 Q 的代表，适合动作可枚举的场景。它的输入是状态—动作，输出每个动作的长期价值估计，策略由“选哪个 Q 更高”间接得到。</p><p><b>策略梯度</b>则直接让参数化策略 <code>πθ(a|s)</code> 输出动作概率，并调整参数 θ。核心更新信号可概括为：</p><div class=\"dd-formula\">∇J≈E[∇logπ<sub>θ</sub>(a|s) · A(s,a)]</div><p><code>J</code> 是期望回报目标；<code>∇logπθ(a|s)</code> 表示怎样改变参数会改变已选动作概率；<b>优势 A(s,a)</b> 表示该动作相对当前状态下通常表现好多少。A 为正就提高该动作概率，为负就降低。它不是新奖励，而是用价值基线消去“这个状态本来就容易或困难”的影响。</p><p><b>Actor–Critic</b>把两条路线组合：Actor 是策略，负责选动作；Critic 是价值估计，负责提供优势基线。这样比直接使用整条随机回报方差更低，但错误 Critic 也会给 Actor 带来有偏方向。</p><p><b>PPO</b>限制新旧策略对已采样动作的概率比，避免一个批次让策略突变。它只限制更新幅度，不保证奖励正确或策略安全；优势若被错误奖励污染，裁剪只会更慢地走错。训练应同时看回报、KL、策略熵、裁剪比例与独立任务指标。</p><p>价值法、策略梯度与 Actor–Critic 描述的是三种利用经验改进策略的计算路线。它们输入状态、动作、回报或价值估计，输出动作价值、策略概率和更新后的参数；价值法先估 Q 再选动作，策略梯度按优势调整概率，Actor–Critic 用 Critic 提供基线。回报上升且 KL、熵和独立任务指标稳定，表示当前更新在多项证据下有效；动作空间、估计偏差和奖励质量会限制方法，PPO 的小步约束也不等于安全保证。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>奖励与环境是边界<span class=\"dd-badge eng\">风险</span></h2><p class=\"dd-lead\">训练回报持续上升，为何仍不能断言真实目标已经达成？</p><p><b>奖励</b>是可计算的目标代理，不是现实价值本身；<b>环境</b>决定动作会产生哪些可见后果，也可能遗漏现实中的副作用。策略会主动寻找二者之间可利用的缝隙：若退款系统只奖励即时满意，它可能学会越权承诺；若模拟器没有欺诈者，策略可能在真实上线后失效。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>边界</th><th>会漏掉什么</th><th>需要的独立证据</th></tr></thead><tbody><tr><td>奖励定义</td><td>未计价的伤害、长期后果</td><td>副作用指标、隐藏终验、人工复核</td></tr><tr><td>状态表示</td><td>权限、历史或上下文信息</td><td>状态充分性测试、失败切片</td></tr><tr><td>模拟环境</td><td>现实噪声与极端参与者</td><td>离线回放、受控小流量验证</td></tr><tr><td>权限边界</td><td>不可逆或高风险动作</td><td>硬约束、审批、可回滚执行</td></tr></tbody></table></div><p>因此结果解释必须同时报告奖励与真实任务指标，并在未参与训练的环境、时间段和风险切片上检查。约束、离线回放与人工监督用于验证副作用，但也不能证明所有未知失败都已覆盖。</p><div class=\"dd-note warn\"><b>RLHF 不是强化学习全部。</b>　它是用人类偏好构造奖励、优化语言策略的一类应用；偏好同样可能有偏差并被策略钻空子。</div><p>奖励与环境共同定义了训练所能“看见”的世界，是强化学习目标的边界而非附属设置。输入是奖励规则、状态表示、转移和权限，输出是策略能够优化的经验分布；策略先在这些规则下行动，再寻找能提高回报的行为模式。训练回报上升只表示更擅长当前代理，若真实解决率、安全切片或副作用恶化，就应解释为目标错位；遗漏后果、模拟差距和不可逆动作都不能靠继续训练自动补回。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>一次退款处理怎样成为 MDP<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">助手面对“35 天质量问题退款”时，为什么立即承诺的短期奖励可能低于先核验再处理的长期回报？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 280\" role=\"img\" aria-label=\"退款助手在未知订单状态下选择直接承诺或核验再处理的 MDP 状态转移\"><defs><marker id=\"rl1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"22\" y=\"91\" width=\"126\" height=\"66\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"85\" y=\"115\" text-anchor=\"middle\" class=\"svg-t\">s₀：订单未知</text><text x=\"85\" y=\"136\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">35 天 · 声称质量问题</text><path d=\"M148,111 L218,61\" stroke=\"#6b7484\" marker-end=\"url(#rl1)\"/><path d=\"M148,140 L218,196\" stroke=\"#6b7484\" marker-end=\"url(#rl1)\"/><rect x=\"220\" y=\"28\" width=\"156\" height=\"74\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"298\" y=\"52\" text-anchor=\"middle\" class=\"svg-t\">a₁：直接承诺退款</text><text x=\"298\" y=\"73\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">即时满意 +4</text><text x=\"298\" y=\"91\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">越权/错误处理 −12（后续）</text><rect x=\"220\" y=\"162\" width=\"156\" height=\"74\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"298\" y=\"186\" text-anchor=\"middle\" class=\"svg-t\">a₂：请求订单与质检</text><text x=\"298\" y=\"207\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">即时摩擦 −1</text><text x=\"298\" y=\"225\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">正确适用例外 +8（后续）</text><path d=\"M376,65 L442,65\" stroke=\"#6b7484\" marker-end=\"url(#rl1)\"/><path d=\"M376,199 L442,199\" stroke=\"#6b7484\" marker-end=\"url(#rl1)\"/><rect x=\"444\" y=\"33\" width=\"112\" height=\"64\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"500\" y=\"57\" text-anchor=\"middle\" class=\"svg-t\">终态：误批</text><text x=\"500\" y=\"79\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">G=4+0.9×(−12)</text><rect x=\"444\" y=\"167\" width=\"112\" height=\"64\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"500\" y=\"191\" text-anchor=\"middle\" class=\"svg-t\">s₁：证据齐全</text><text x=\"500\" y=\"213\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">G=−1+0.9×8</text><path d=\"M556,199 L610,199\" stroke=\"#6b7484\" marker-end=\"url(#rl1)\"/><text x=\"635\" y=\"191\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">正确处理</text><text x=\"635\" y=\"209\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">终态</text><text x=\"340\" y=\"270\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">价值估计把延迟后果传回当前动作；若奖励只记录即时满意，策略会学会过度承诺</text></svg><figcaption>图 1　强化学习评价动作对未来状态和奖励的影响；核验虽有即时摩擦，却可能拥有更高折扣回报。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>动作</th><th>r₁</th><th>r₂</th><th>γ=0.9 的 G</th><th>选择</th></tr></thead><tbody><tr><td>直接承诺</td><td>+4</td><td>−12</td><td>4−10.8=−6.8</td><td>拒绝</td></tr><tr><td>先核验</td><td>−1</td><td>+8</td><td>−1+7.2=6.2</td><td>优选</td></tr><tr><td>只优化即时奖励</td><td>+4 vs −1</td><td>忽略</td><td>错误选直接承诺</td><td>短视</td></tr></tbody></table></div><p>信用分配要把后续 −12 或 +8 归因到首个动作。时序差分可用 <code>δ=r+γV(s′)−V(s)</code> 更新价值；若当前 V(s₀)=0、核验后状态 V(s₁)=8，则核验动作的一步 TD 目标为 <code>−1+0.9×8=6.2</code>。奖励延迟越长、环境越随机，估计方差越大。</p><div class=\"dd-note key\"><b>状态边界：</b>若 s₀ 没有用户权限、订单日期和证据状态，策略无法区分应直接回答与应核验的情境；奖励再精确也补不回被状态表示丢掉的决策信息。</div><p>退款案例是一条完整的信用分配演算：输入订单状态、两个候选动作、两步奖励和折扣因子，输出各动作回报与首步选择。计算先列出即时奖励，再把后续奖励折扣回首个动作，最后比较 −6.8 与 6.2；先核验胜出表示延迟后果足以推翻即时满意。这个结论依赖状态包含权限和证据、奖励数值合理；关键信息缺失或后果漏记，都可能让 TD 更新更高效地学习错误策略。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>探索、离线数据和策略更新怎样失效<span class=\"dd-badge eng\">失败边界</span></h2><p class=\"dd-lead\">为什么不能让退款助手在线随机尝试越权动作来“探索”？</p><p>探索的价值是获得未知动作后果，但真实系统有不可接受代价。可先在模拟器、历史日志或受限沙箱学习，再用安全策略约束上线；离线 RL 又面临分布外动作价值被过高估计，因为数据从未展示其真实后果。策略改进后访问的状态分布改变，旧评估可能失效。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>失败</th><th>机制</th><th>防线</th></tr></thead><tbody><tr><td>危险探索</td><td>为获信息尝试高风险动作</td><td>安全集合、模拟器、审批</td></tr><tr><td>离线外推</td><td>未见动作 Q 值虚高</td><td>保守估计、行为约束、真实小流量验证</td></tr><tr><td>奖励投机</td><td>利用代理或环境漏洞</td><td>隐藏终验、副作用指标、权限隔离</td></tr><tr><td>策略崩塌</td><td>更新过大导致行为突变</td><td>PPO/KL、回滚点、分阶段闸门</td></tr><tr><td>非平稳环境</td><td>用户/规则随时间变化</td><td>漂移监控与重新评估</td></tr></tbody></table></div><p>PPO 的裁剪目标限制单次概率比变化，却不证明长期安全；即使每步更新小，许多步累积仍会远离参考策略。要同时监控 KL、关键行为回归和真实环境指标。</p><p>安全强化学习工作流是把探索、离线估计、策略更新和上线闸门放进同一风险控制过程，用于降低危险探索、离线外推和策略突变的风险。它输入历史日志、模拟器、安全动作集、候选策略和监控指标，输出受约束策略及放行或回滚决定；先在离线或沙箱学习，再用保守估计和小流量验证，随后持续监控 KL、行为与真实指标。小步更新和离线高分只表示局部证据较好，不能证明长期安全；分布外动作、非平稳环境和奖励投机不能只靠算法分数处理，仍要求人工与硬约束。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">强化学习是序列决策框架，不等于“有奖励就训练”或某一个 PPO 算法。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>每步奖励最高就是最优策略</td><td>应最大化长期折扣回报，动作会改变未来状态</td></tr><tr><td>探索就是随机乱试</td><td>应权衡信息价值与风险，并受安全边界约束</td></tr><tr><td>价值函数是事实</td><td>它是特定策略和数据下的期望估计，会有偏差</td></tr><tr><td>PPO 保证策略安全</td><td>它限制更新幅度，不保证奖励、环境和权限正确</td></tr><tr><td>RLHF 就是强化学习</td><td>RLHF 是用人类偏好代理优化语言策略的一类应用</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>概率、期望、梯度下降、监督学习</td></tr><tr><td><b>本页核心</b></td><td>MDP、回报、V/Q、Bellman、TD、探索与策略梯度</td></tr><tr><td>紧邻</td><td>RLHF、奖励投机、世界模型、智能体规划</td></tr><tr><td>工程延伸</td><td>离线 RL、人在回路、测试时计算、安全约束与可观测性</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>策略选择动作</li><li>环境返回状态与奖励</li><li>多步奖励形成回报</li><li>价值估计承担信用分配</li><li>探索产生新经验</li><li>独立评测检查奖励是否代表真实目标</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>强化学习的一步交互包含哪些对象？策略的输入和输出分别是什么？</li><li>现在奖励为 −1、下一步奖励为 +8，γ=0.9。计算两步回报，并解释为什么它可能优于即时奖励为 +4、下一步为 −12 的动作。</li><li>Vπ(s) 与 Qπ(s,a) 的输入和含义有什么区别？为什么一次幸运轨迹不能证明价值高？</li><li>用白话解释 Bellman 递推解决了什么问题，γ 和 s′ 在式中分别表示什么。</li><li>策略梯度中的优势 A(s,a) 为正或为负时分别怎样更新？它为什么不是一种新奖励？</li><li>为什么探索不等于随机乱试？退款助手面对未知高风险动作时应怎样获得证据？</li><li>PPO 的裁剪能保证哪些事情，又不能保证哪些事情？</li><li>训练回报和离线成功率都上升后，设计三个验收切片，并说明不可被平均值抵消的失败边界。</li><li>假设“强化学习：从延迟反馈中学习决策策略”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>环境给出状态 s，策略 π(a|s) 以状态为输入并输出动作或动作概率；智能体执行动作 a 后，环境返回奖励 r 和下一状态 s′。学习结果是一套状态到动作的决策规则，而不是某一道题的固定答案。</li><li>前者 G=−1+0.9×8=6.2；后者 G=4+0.9×(−12)=−6.8。只看即时奖励会选择 +4，但折扣回报把延迟后果也计入，因此应选择先付出一点核验成本、长期结果更好的动作。</li><li>V 输入状态，估计从该状态遵循 π 的期望回报；Q 还固定当前动作，估计先做该动作、之后遵循 π 的期望回报。两者都对策略选择和环境随机性求平均，一次轨迹只是一个带噪样本。</li><li>它把很长的未来拆成“眼前一步奖励 + 下一状态剩余价值”，因而不必每次等整条轨迹结束。s′ 是执行当前动作后的下一状态，γ 是折扣因子，用来降低更远奖励在当前估计中的权重。</li><li>A 为正时提高已选动作在该状态下的概率，为负时降低。优势由动作回报减去状态基线得到，表示这个动作相对该状态通常水平好多少；它重新中心化已有回报信号，并未定义新的现实目标。</li><li>探索的目的应是减少影响决策的关键不确定性，重复已知坏动作只有风险没有信息价值。高风险动作应先在模拟器、历史日志或受限沙箱中验证，并受权限、审批和可回滚约束，不能直接对真实用户随机试错。</li><li>裁剪限制一次更新中新旧策略概率比的变化，降低单个批次导致行为突变的风险；它不能保证奖励代表真实目标、状态信息充分、权限正确或长期安全，许多小步累积也会远离参考策略。</li><li>可按权限风险切片，越权动作率必须为零或低于硬上限；按订单年龄与证据完整度切片，分别报告正确处理率和人工接管率；按时间或用户群切片，检查环境变化后的回报和真实解决率。越权、不可逆伤害等红线不能由普通案例的高平均分抵消。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"http://incompleteideas.net/book/RLbook2020.pdf\" target=\"_blank\" rel=\"noopener\">Reinforcement Learning: An Introduction</a>：MDP、价值与策略基础</li><li><a href=\"https://arxiv.org/abs/1312.5602\" target=\"_blank\" rel=\"noopener\">Playing Atari with Deep Reinforcement Learning</a>：DQN</li><li><a href=\"https://arxiv.org/abs/1707.06347\" target=\"_blank\" rel=\"noopener\">Proximal Policy Optimization Algorithms</a>：PPO</li><li><a href=\"https://arxiv.org/abs/2006.04779\" target=\"_blank\" rel=\"noopener\">Conservative Q-Learning for Offline Reinforcement Learning</a>：离线分布外动作的保守价值估计</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
